-- Flyway Migration V2: Migrate from BIGSERIAL to TSID (application-generated IDs)
-- This migration truncates all tables and removes auto-increment from ID columns.
-- TSID IDs are generated by the application using hypersistence-utils.

-- Disable FK checks for truncation
SET session_replication_role = 'replica';

-- Truncate all tables (in reverse dependency order)
TRUNCATE TABLE notifications CASCADE;
TRUNCATE TABLE message_thread_participants CASCADE;
TRUNCATE TABLE messages CASCADE;
TRUNCATE TABLE message_threads CASCADE;
TRUNCATE TABLE trip_participations CASCADE;
TRUNCATE TABLE trip_day_rides CASCADE;
TRUNCATE TABLE trip_days CASCADE;
TRUNCATE TABLE ride_participations CASCADE;
TRUNCATE TABLE ride_groups CASCADE;
TRUNCATE TABLE rides CASCADE;
TRUNCATE TABLE trips CASCADE;
TRUNCATE TABLE route_points_of_interest CASCADE;
TRUNCATE TABLE route_climbs CASCADE;
TRUNCATE TABLE gpx_tracks CASCADE;
TRUNCATE TABLE routes CASCADE;
TRUNCATE TABLE places CASCADE;
TRUNCATE TABLE team_domains CASCADE;
TRUNCATE TABLE user_teams CASCADE;
TRUNCATE TABLE teams CASCADE;
TRUNCATE TABLE users CASCADE;

-- Re-enable FK checks
SET session_replication_role = 'origin';

-- Remove SERIAL/BIGSERIAL auto-increment from ID columns
-- (The sequences are no longer needed since IDs are generated by the application)

-- Users
ALTER TABLE users ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS users_id_seq;

-- Teams
ALTER TABLE teams ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS teams_id_seq;

-- User Teams
ALTER TABLE user_teams ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS user_teams_id_seq;

-- Team Domains
ALTER TABLE team_domains ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS team_domains_id_seq;

-- Places
ALTER TABLE places ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS places_id_seq;

-- Routes
ALTER TABLE routes ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS routes_id_seq;

-- GPX Tracks
ALTER TABLE gpx_tracks ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS gpx_tracks_id_seq;

-- Route Climbs
ALTER TABLE route_climbs ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS route_climbs_id_seq;

-- Route POIs
ALTER TABLE route_points_of_interest ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS route_points_of_interest_id_seq;

-- Rides
ALTER TABLE rides ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS rides_id_seq;

-- Ride Groups
ALTER TABLE ride_groups ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS ride_groups_id_seq;

-- Ride Participations
ALTER TABLE ride_participations ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS ride_participations_id_seq;

-- Trips
ALTER TABLE trips ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS trips_id_seq;

-- Trip Days
ALTER TABLE trip_days ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS trip_days_id_seq;

-- Trip Day Rides
ALTER TABLE trip_day_rides ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS trip_day_rides_id_seq;

-- Trip Participations
ALTER TABLE trip_participations ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS trip_participations_id_seq;

-- Message Threads
ALTER TABLE message_threads ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS message_threads_id_seq;

-- Messages
ALTER TABLE messages ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS messages_id_seq;

-- Message Thread Participants
ALTER TABLE message_thread_participants ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS message_thread_participants_id_seq;

-- Notifications
ALTER TABLE notifications ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS notifications_id_seq;
